function acon(id,p=prog()){id=typeof id==='object'?id.id:id;const c=p.athleteContracts[id];return c&&c.state==='active'?c:null}function archiveAthleteContract(p,c,outcome){if(!p||!c)return;p.athleteContractHistory??=[];if(c.archived)return;c.archived=true;c.outcome=outcome||c.state||'ended';c.endedCareerWeek=Number(c.endedCareerWeek||cw());p.athleteContractHistory.push({...c});p.athleteContractHistory=p.athleteContractHistory.slice(-300)}function athleteContractHistory(id,p=prog()){id=typeof id==='object'?id.id:id;return (p.athleteContractHistory||[]).filter(c=>String(c.athleteId)===String(id)).sort((a,b)=>Number(b.endedCareerWeek||0)-Number(a.endedCareerWeek||0))}function scon(r,p=prog()){const c=p.staffContracts[r];return c&&c.state==='active'?c:null}
function fact(k,p=prog()){return clamp(p.facilities[k]?.level||1,1,5)}function fcond(k,p=prog()){return clamp(p.facilities[k]?.condition??100,0,100)}function fcap(k,p=prog()){return FAC[k].cap[fact(k,p)-1]}
function fup(k,p=prog()){const l=fact(k,p),m=[0,1,1.38,1.82,2.42,3.15][l],load=fcond(k,p)<60?1.1:fcond(k,p)<75?1.04:1;return Math.round(FAC[k].base*m*costFactor(p.nation||nation())*inf()*load/100)*100}
function feff(k){const p=prog(),f=p.facilities[k];if(!f)return Number(s.facilityLevels?.[k]||1);const l=fact(k,p),cf=.55+.45*fcond(k,p)/100,build=f.construction?.weeksRemaining>0?.9:1,temp=Number(f.temporaryRepairUntil||0)>cw()?.93:1;return clamp(1+(l-1)*cf*build*temp,1,l)}
const fbuild=k=>Math.round(FAC[k].build*Math.pow(Math.min(5,fact(k)+1),1.18)*costFactor()*inf()/10000)*10000,fweeks=k=>6+fact(k)*2,fservice=k=>Math.max(45000,Math.round((100-fcond(k))*1450*fact(k)*costFactor()*inf()/5000)*5000);
const FACILITY_ISSUES={sprint:[['Indoor track surface deterioration','Sections of the indoor sprint surface have failed inspection. Full-speed work is being restricted until the surface is made safe.'],['Timing-system failure','The primary sprint timing and start-analysis equipment has failed calibration and cannot currently provide reliable testing data.']],field:[['Throws-sector equipment failure','Specialist field-event equipment has failed inspection. Technical work can continue, but the centre is operating below normal capability.'],['Runway and landing-area repairs','Wear has been identified across the jumps runway and landing infrastructure. The centre remains usable with restrictions.']],recovery:[['Recovery equipment failure','A key recovery system has failed and the medical team has reduced throughput until repairs are completed.'],['Ventilation and treatment-suite fault','An operational fault is affecting part of the recovery and treatment area. Capacity is reduced while the issue remains unresolved.']]};
function makeFacilityIncident(k,p){const f=p.facilities[k];if(!f||f.incident)return null;const choices=FACILITY_ISSUES[k]||FACILITY_ISSUES.recovery,spec=choices[hash(`${k}-${cw()}-issue`)%choices.length],level=fact(k,p),full=Math.max(fservice(k),Math.round((80000+level*52000)*costFactor()*inf()/5000)*5000),temporary=Math.round(full*.32/5000)*5000,drop=5+(hash(`${cw()}-${k}-damage`)%8);f.condition=clamp(f.condition-drop,20,100);f.incident={id:`${k}-${cw()}`,title:spec[0],body:spec[1],createdCareerWeek:cw(),fullCost:full,temporaryCost:temporary,deferredUntil:0};p.lastIncident=cw();mail('performance',`${FAC[k].name}: ${spec[0]}`,`${spec[1]} Finance → Facilities now has three options: complete repair ${cash(full)}, temporary repair ${cash(temporary)}, or defer the work. The centre is currently at ${Math.round(f.condition)}% condition.`,'review');return f.incident}
function resolveFacilityIncident(k,choice){const p=prog(),f=p.facilities[k],i=f?.incident;if(!i)return false;if(choice==='full'){if(Number(s.funding)<Number(i.fullCost)){toastNow('Not enough funding for the full repair');return false}post(-Number(i.fullCost),`${FAC[k].name}: ${i.title} — full repair`,'Facilities',{maintenance:true,facility:k,incident:i.id});f.condition=100;f.incident=null;f.temporaryRepairUntil=0;f.lastBand=null;p.boardTrust=clamp(Number(p.boardTrust||65)+.8,0,100);mail('performance',`${FAC[k].name}: full repair authorised`,`The ${i.title.toLowerCase()} has been fully resolved. The centre has returned to 100% condition.`)}else if(choice==='temporary'){if(Number(s.funding)<Number(i.temporaryCost)){toastNow('Not enough funding for the temporary repair');return false}post(-Number(i.temporaryCost),`${FAC[k].name}: ${i.title} — temporary repair`,'Facilities',{maintenance:true,temporary:true,facility:k,incident:i.id});f.condition=clamp(Math.max(f.condition+22,72),20,88);f.temporaryRepairUntil=cw()+26;f.incident=null;f.lastBand=f.condition<70?'watch':null;mail('performance',`${FAC[k].name}: temporary repair completed`,`The centre remains open after a temporary repair. Condition is ${Math.round(f.condition)}%; a small effectiveness penalty remains for the next 26 weeks.`)}else if(choice==='defer'){if(Number(i.deferredUntil||0)>cw()){toastNow(`Decision already deferred until career week ${i.deferredUntil}`);return false}i.deferredUntil=cw()+4;f.condition=clamp(f.condition-1.5,20,100);p.boardTrust=clamp(Number(p.boardTrust||65)-.6,0,100);mail('board',`${FAC[k].name}: repair deferred`,`You have deferred the ${i.title.toLowerCase()} for four weeks. No money has been spent, but the facility remains below full effectiveness and condition may deteriorate further.`,'review')}saveNow();drawFinance2();return true}
function athletePay(p=prog()){return Object.values(p.athleteContracts).filter(c=>c.state==='active'&&weeks(c)>0).reduce((n,c)=>n+Number(c.annualFunding||0)/52,0)}function staffPay(p=prog()){return Object.values(p.staffContracts).filter(c=>c.state==='active'&&weeks(c)>0).reduce((n,c)=>n+Number(c.annualSalary||0)/52,0)}function facilityPay(p=prog()){return Object.keys(FAC).reduce((n,k)=>n+fup(k,p),0)}
function ops(){const st=s.staff||{};return Math.round((2800+team().length*390+(Number(st.physio||1)+Number(st.science||1))*720+Number(st.scout||1)*480)*costFactor()*inf()/100)*100}
function weekly(p=prog()){const athlete=Math.round(athletePay(p)),staff=Math.round(staffPay(p)),facilities=Math.round(facilityPay(p)),operations=Math.round(ops());return{athlete,staff,facilities,operations,total:athlete+staff+facilities+operations}}
function snap(p=prog()){const w=weekly(p),left=Math.max(0,53-wk()),projected=Number(s.funding||0)-w.total*left,run=w.total?Number(s.funding||0)/w.total:99;let health=run>=26?'healthy':run>=13?'watch':run>=6?'restricted':'critical';if(Number(s.funding)<0)health='critical';p.health=health;const exp=Object.values(p.athleteContracts).filter(c=>c.state==='active'&&weeks(c)<=12).length+Object.values(p.staffContracts).filter(c=>c.state==='active'&&weeks(c)<=12).length;return{weekly:w,left,projected,runway:run,health,committed:w.total*left,unallocated:Number(s.funding||0)-w.total*13,core:indexedGrant(),expiring:exp}}
const restricted=(p=prog())=>{const g=p?.governance||{},c=g.control;return snap(p).health==='critical'||cw()<Number(p.restrictionUntil||0)||!!(c&&cw()<Number(c.endCareerWeek||0))};
function boardControl(p,weeks,kind,reason){p.governance??={};const end=cw()+Math.max(1,Number(weeks)||1);p.restrictionUntil=Math.max(Number(p.restrictionUntil||0),end);p.governance.control={kind:kind||'expansion',reason:reason||'Board spending controls',startCareerWeek:cw(),endCareerWeek:end};return p.governance.control}
function activeBoardControl(p=prog()){const c=p?.governance?.control;if(c&&cw()>=Number(c.endCareerWeek||0)){p.governance.control=null}else if(c)return c;const legacyEnd=Number(p?.restrictionUntil||0);return cw()<legacyEnd?{kind:'temporary',reason:'Temporary board spending controls',endCareerWeek:legacyEnd}:null}
function removeEntries(a){(s.events||[]).filter(e=>!e.completed).forEach(e=>Object.keys(e.entries||{}).forEach(d=>{if((e.entries[d]||[]).includes(a.id)){e.entries[d]=e.entries[d].filter(id=>id!==a.id);e.decision=false}}))}
function facilityWeek(p){for(const [k,f] of Object.entries(p.facilities)){if(f.construction){f.construction.weeksRemaining=Math.max(0,Number(f.construction.weeksRemaining)-1);if(!f.construction.weeksRemaining){f.level=f.construction.targetLevel;f.condition=100;s.facilityLevels??={};s.facilityLevels[k]=f.level;f.construction=null;f.lastBand=null;mail('performance',`${FAC[k].name} upgrade complete`,`${FAC[k].name} is now Level ${f.level}. Weekly upkeep is ${cash(fup(k,p))}; capacity is ${fcap(k,p)} athletes.`)}}if(Number(f.temporaryRepairUntil||0)&&cw()>=Number(f.temporaryRepairUntil)){f.temporaryRepairUntil=0;mail('performance',`${FAC[k].name}: temporary repair period ended`,`The temporary repair period has ended. Current condition is ${Math.round(f.condition)}%. Routine servicing can restore full condition, while future faults may require a new operational decision.`)}f.condition=clamp(Number(f.condition||100)-(.06+fact(k,p)*.025+(hash(`${yr()}-${wk()}-${k}`)%9)/100),20,100);if(f.incident&&Number(f.incident.deferredUntil||0)>0&&cw()>=Number(f.incident.deferredUntil)){f.incident.deferredUntil=0;f.condition=clamp(f.condition-3,20,100);mail('performance',`${FAC[k].name}: deferred repair now due`,`${f.incident.title} remains unresolved. Condition has fallen to ${Math.round(f.condition)}%. Review Finance → Facilities before the problem causes further performance loss.`,'review')}const b=f.condition<50?'critical':f.condition<70?'watch':null;if(b&&f.lastBand!==b){f.lastBand=b;mail('performance',`${FAC[k].name}: maintenance required`,`${FAC[k].name} is operating at ${Math.round(f.condition)}% condition. Its contribution is below its headline level. Open Finance → Facilities to review servicing.`)}if(!f.construction&&!f.incident&&f.condition<86&&cw()-Number(p.lastIncident||0)>32&&(hash(`${cw()}-${k}-incident`)%1000)<10)makeFacilityIncident(k,p)}}
function athleteExpiries(p){for(const c of Object.values(p.athleteContracts)){if(c.state!=='active')continue;const a=s.athletes.find(x=>x.id===c.athleteId);if(!a)continue;const l=weeks(c);if(l<=0){c.state='expired';archiveAthleteContract(p,c,'expired');a.inSquad=false;a.squadCommitUntil=0;a.poolEnteredCareerWeek=cw();removeEntries(a);safe(()=>rememberAthlete(a,'Programme contract','National programme agreement expired. Returned to club-led competition.'),null);mail('performance',`Programme agreement ended: ${a.name}`,`${a.name}'s funded national programme agreement has expired. ${a.athleticsClub||'Their club'} now controls normal competition activity. The athlete remains available for a future national call-up.`,'contract')}else if(l<=8&&!c.warned){c.warned=true;mail('performance',`Contract decision: ${a.name}`,`${a.name} has ${l} weeks remaining on a ${c.status} agreement worth ${cash(c.annualFunding)} per year. Review it in Finance → Contracts.`,'contract')}}}
function staffExpiries(p){for(const [r,c] of Object.entries(p.staffContracts)){if(c.state!=='active')continue;const coach=s.coaches?.[r],l=weeks(c);if(l<=0){c.state='expired';if(coach){safe(()=>recordCoachMove(coach,`Left ${nlabel()} at contract expiry.`),null);if(coachAge(coach)>=70)recordStaffWorldMove(coach,nation(),null,r,'retired');else freeAgentAdd({...coach,role:r,expectedSalary:Number(c.annualSalary||coachSalary(r,coach)),annualSalary:Number(c.annualSalary||0)},nation(),'contract expiry')}s.coaches[r]=null;s.staff[r]=1;mail('performance',`Staff contract ended: ${coach?.name||roleName(r)}`,`${coach?.name||'The specialist'} has left the ${roleName(r)} role. Interim Level 1 cover is in place while you recruit a replacement.`,'contract')}else if(l<=8&&!c.warned){c.warned=true;mail('performance',`Staff renewal due: ${coach?.name||roleName(r)}`,`${l} weeks remain on the current contract at ${cash(c.annualSalary)} per year. Review the role in Staff.`,'contract')}}}
function seasonRank(){const i=Number(safe(()=>nationRanks().findIndex(x=>x[0]===nation()),-1));return i>=0?i+1:8}
function seasonInternationalPodiums(){return safe(()=>importManagerResults().filter(x=>Number(x.season)===yr()&&!x.national).flatMap(x=>x.rows||[]).filter(r=>Number(r.place)<=3).length,0)}
function ensureBoardMandate(p=prog()){const g=p.governance;g.mandateHistory??=[];if(g.mandate&&Number(g.mandate.season)===yr())return g.mandate;if(g.mandate&&Number(g.mandate.season)!==yr())g.mandate=null;if(wk()>10||g.mandateHistory.some(x=>Number(x.season)===yr()))return null;const rank=seasonRank(),x=snap(p),eligible=Number(p.boardTrust||0)>=50&&x.health!=='critical',advance=Math.round(indexedGrant()*.08/5000)*5000,targetRank=Math.max(1,rank-1),targetPodiums=rank<=4?3:2;g.mandate={id:`mandate-${yr()}`,season:yr(),status:'open',offeredWeek:wk(),deadlineWeek:10,rankAtOffer:rank,eligible,advance,targetRank,targetPodiums};mail('board','Annual funding mandate available',`The federation is prepared to discuss a performance-linked advance of ${cash(advance)}. Accepting it would set a season target of nation rank #${targetRank} or better and ${targetPodiums} international podiums. The advance is never clawed back, but missing the mandate will reduce board confidence and trigger temporary spending controls.`,'review');return g.mandate}
function chooseBoardMandate(choice,p=prog()){const g=p.governance,m=ensureBoardMandate(p);if(!m||m.status!=='open')return false;if(choice==='baseline'){m.status='baseline';m.resolvedWeek=wk();p.boardTrust=clamp(Number(p.boardTrust||65)+1,0,100);g.mandateHistory.push({...m,outcome:'baseline'});mail('board','Funding mandate: baseline plan confirmed','The programme will operate on its normal federation allocation with no additional performance condition attached.','info')}else if(choice==='accelerator'){if(!m.eligible){toastNow('The board will not approve a performance advance in the current financial position');return false}m.status='active';m.acceptedWeek=wk();post(m.advance,'Federation performance advance','Federation',{mandate:true});mail('board','Performance funding mandate agreed',`${cash(m.advance)} has been released immediately. The season target is nation rank #${m.targetRank} or better and ${m.targetPodiums} international podiums. The funding is not repayable, but missing the mandate will reduce board confidence.`,'review')}else return false;saveNow();drawFinance2();return true}
function settleBoardMandate(p=prog()){const g=p.governance,m=g.mandate;if(!m||Number(m.season)!==yr()||m.status==='settled')return;if(m.status==='open'){m.status='baseline';g.mandateHistory.push({...m,outcome:'expired-baseline'});return}if(m.status!=='active')return;const rank=seasonRank(),podiums=seasonInternationalPodiums(),met=rank<=Number(m.targetRank)&&podiums>=Number(m.targetPodiums);m.status='settled';m.finalRank=rank;m.finalPodiums=podiums;m.met=met;m.settledWeek=wk();if(met){p.boardTrust=clamp(Number(p.boardTrust||65)+6,0,100);mail('board','Performance mandate achieved',`The programme finished at nation rank #${rank} with ${podiums} international podiums. The federation considers the performance advance well used; board confidence has increased.`,'review')}else{p.boardTrust=clamp(Number(p.boardTrust||65)-10,0,100);boardControl(p,8,'performance',`Missed ${yr()} performance funding mandate`);mail('board','Performance mandate missed',`The programme finished at nation rank #${rank} with ${podiums} international podiums, below the agreed mandate. The advance is not clawed back, but board confidence has fallen and expansion spending is restricted for eight weeks.`,'review')}g.mandateHistory.push({...m,outcome:met?'met':'missed'});g.mandateHistory=g.mandateHistory.slice(-40)}
function createBoardIntervention(p,x=snap(p),reason='financial pressure'){const g=p.governance;const existing=g.intervention;if(existing?.status==='pending')return existing;if(cw()-Number(g.lastControl||0)<12)return null;const level=x.health==='critical'||Number(s.funding)<0?'critical':'recovery';g.lastControl=cw();g.intervention={id:`board-${cw()}-${level}`,status:'pending',level,reason,createdCareerWeek:cw(),deadlineCareerWeek:cw()+3,runway:Math.max(0,Math.round(x.runway)),projected:Number(x.projected||0),weekly:Number(x.weekly.total||0)};mail('board',level==='critical'?'Board intervention: programme stabilisation required':'Board intervention: recovery plan required',`The programme is under ${level==='critical'?'critical':'material'} financial pressure. A response is required in Finance → Board within three weeks. You can accept a recovery plan, ring-fence current athlete support, or request federation stabilisation funding. Ignoring the request will result in imposed controls.`,'review');return g.intervention}
function respondBoard(choice,p=prog()){const g=p.governance,x=snap(p),i=g.intervention;if(!i||i.status!=='pending')return false;let label='',grant=0,weeks=0,trust=0;if(choice==='recovery'){label='Manager-led recovery plan';weeks=8;trust=5;boardControl(p,weeks,'recovery','Manager-led recovery plan')}else if(choice==='protect'){label='Athlete programme protection';grant=Math.round(Number(x.weekly.athlete||0)*4/5000)*5000;weeks=10;trust=1;if(grant)post(grant,'Federation athlete programme protection','Federation',{intervention:true});boardControl(p,weeks,'protected-programme','Protect existing athlete programme')}else if(choice==='support'){label='Federation stabilisation support';grant=Math.ceil(Math.max(Number(x.weekly.total||0)*6,Math.abs(Math.min(0,Number(s.funding||0)))+Number(x.weekly.total||0)*4)/10000)*10000;weeks=12;trust=-5;if(grant)post(grant,'Federation stabilisation support','Federation',{intervention:true,emergency:true});boardControl(p,weeks,'stabilisation','Federation stabilisation support')}else return false;p.boardTrust=clamp(Number(p.boardTrust||65)+trust,0,100);i.status='resolved';i.choice=choice;i.outcome=label;i.resolvedCareerWeek=cw();i.grant=grant;i.controlWeeks=weeks;g.history.push({...i});g.history=g.history.slice(-80);mail('board',`Board response agreed: ${label}`,`${grant?`${cash(grant)} has been released. `:''}Expansion spending will be controlled for ${weeks} weeks while existing athlete and staff commitments continue. Board financial confidence is now ${Math.round(p.boardTrust)}/100.`,'review');saveNow();drawFinance2();return true}
function boardWeek(p,x=snap(p)){const g=p.governance,c=activeBoardControl(p);if(c&&cw()+1>=Number(c.endCareerWeek||0)&&!c.reviewNotified){c.reviewNotified=true;const better=['healthy','watch'].includes(x.health);p.boardTrust=clamp(Number(p.boardTrust||65)+(better?3:-4),0,100);mail('board',better?'Board controls approaching release':'Board controls remain under review',better?'The programme has stabilised. Expansion authority will return when the current control period ends.':'The control period is ending but the budget remains under pressure. Further intervention may follow if the position does not improve.','review')}
 const pending=g.intervention;if(pending?.status==='pending'&&cw()>=Number(pending.deadlineCareerWeek||0)){const grant=Number(s.funding)<0?Math.ceil((Math.abs(Number(s.funding))+Number(x.weekly.total||0)*4)/10000)*10000:0;if(grant)post(grant,'Imposed federation liquidity support','Federation',{intervention:true,imposed:true});p.boardTrust=clamp(Number(p.boardTrust||65)-8,0,100);boardControl(p,12,'imposed','Board-imposed stabilisation controls');pending.status='imposed';pending.choice='imposed';pending.grant=grant;pending.resolvedCareerWeek=cw();g.history.push({...pending});g.history=g.history.slice(-80);mail('board','Federation imposes stabilisation controls',`${grant?`${cash(grant)} has been released to protect existing commitments. `:''}The response deadline passed without an agreed plan. Expansion spending is restricted for twelve weeks and board confidence has fallen.`,'review')}
 if(!g.intervention||g.intervention.status!=='pending'){if(x.health==='critical'||x.health==='restricted')createBoardIntervention(p,x,`${x.health} financial health`);else if(Number(p.boardTrust||65)<30)createBoardIntervention(p,x,'low board confidence')}
 ensureBoardMandate(p)}
function applyGovernance(p,x=snap(p)){p.governance??={lastHealth:p.health||'healthy',lastNotice:0,lastControl:0,history:[],mandateHistory:[]};const g=p.governance,prev=g.lastHealth||'healthy',now=x.health,canNotice=cw()-Number(g.lastNotice||0)>=3;if(prev!==now&&canNotice){g.lastNotice=cw();if(now==='watch')mail('board','Budget position moved to watch',`The programme now has roughly ${Math.max(0,Math.round(x.runway))} weeks of operating runway. Existing commitments are secure, but the board expects new spending to be considered against the season-end forecast.`,'review');else if(['restricted','critical'].includes(now))createBoardIntervention(p,x,`${now} financial health`);else if(now==='healthy'&&['watch','restricted','critical'].includes(prev))mail('board','Programme finances returned to a healthy position',`Available funding and current commitments now provide ${Math.max(0,Math.round(x.runway))} weeks of operating runway. Existing board controls will expire on their stated timetable.`,'review')}if(Number(p.boardTrust||65)<30)createBoardIntervention(p,x,'low board confidence');g.lastHealth=now}

function runEconomy(){const p=prog();if(Number(p.lastWeekly)===cw())return;p.lastWeekly=cw();facilityWeek(p);const w=weekly(p);if(w.athlete)post(-w.athlete,'Athlete programme payroll','Athlete Contracts',{recurring:true});if(w.staff)post(-w.staff,'Performance staff payroll','Staff',{recurring:true});if(w.facilities)post(-w.facilities,'National facility upkeep','Facilities',{recurring:true});if(w.operations)post(-w.operations,'Performance operations','Operations',{recurring:true});athleteExpiries(p);staffExpiries(p);const x=snap(p);if(x.health==='critical')p.boardTrust=clamp(Number(p.boardTrust||65)-.4,0,100);else if(x.health==='healthy')p.boardTrust=clamp(Number(p.boardTrust||65)+.08,0,100);applyGovernance(p,x);boardWeek(p,x)}
function dialog(){let d=document.getElementById('programmeEconomyDialog');if(!d){d=document.createElement('dialog');d.id='programmeEconomyDialog';d.className='pe-modal';document.body.appendChild(d);d.addEventListener('cancel',e=>{e.preventDefault();closeD()})}return d}function closeD(){const d=document.getElementById('programmeEconomyDialog');try{if(d?.open)d.close()}catch(_){}}
